-- 105: Pacific fishing rules (US plan step 4): Washington, Oregon, California
-- Checked 2026-10-22 in each state's own guide (links in source_url): Washington Sport Fishing Rules July 1, 2026 – June 30, 2027 (WDFW's official
-- pamphlet, linked from wdfw.wa.gov/fishing/regulations: Statewide Freshwater Species Rules p. 24-25, Statewide Marine Area Rules p. 108, Marine Area
-- Rules p. 110-131); 2026 Oregon Sport Fishing Regulations (ODFW's official book, linked from myodfw.com/fishing/regulations: the zone regulations
-- for the Northwest, Southwest, Willamette, Central, Northeast, Southeast, Snake River and Columbia River zones, and the Marine Zone p. 81);
-- California 2026 Ocean Sport Fishing Regulations (updated July 17, 2026; summary table p. 45-49), CDFW's Recreational Groundfish Summary page
-- (updated June 23, 2026) and the 2026 California Freshwater Sport Fishing Regulations (updated July 10, 2026; species regulations p. 27-34),
-- all linked from wildlife.ca.gov/Regulations.
-- A state rule is a normal fish_rules row whose `regions` holds the 2-letter state code. Needs setup/94 first (its check already allows these codes).
-- Where a rule changes by area, zone, water or season the app can only show one number, so the STRICTER one is the size / bag and the note has the rest
-- (Washington: the strictest marine area; Oregon: the strictest zone; California: the strictest district / management area). Closed dates are only
-- added where the main way of fishing for that fish closes (Washington lingcod and cabezon, California groundfish boats, ocean salmon, Pacific halibut).
-- NOT added: crabs and lobster (their size is a shell width, and the app can only show total or fork length — the Dungeness crab card explains it),
-- river salmon seasons (set water by water), Oregon ocean bottomfish bag limits (set after the book is printed).
-- Insert only; no delete / drop.

insert into fish_rules (species, match, regions, min_in, max_in, measure, one_over, bag, release_only, closed, open_only, note, source_url, verified_on, active) values
-- ---------------- Washington (WDFW Sport Fishing Rules 2026-27: statewide freshwater rules, statewide and area marine rules) ----------------
 ('Trout (rainbow, brown, cutthroat, golden, tiger) and grayling', array['rainbow trout','brown trout','cutthroat','golden trout','tiger trout','grayling'], array['WA'], 8, null, 'total', false, '2 per day in rivers and streams (8″ minimum)', false, null, null,
  'Lakes, ponds and reservoirs: 5 per day, no minimum. Fishing rivers and lakes the same day: 5 trout, only 2 from rivers. Rivers and streams are open the Saturday before Memorial Day – Oct 31 unless a water''s special rules say otherwise. When fishing with bait, every legal trout you catch counts, kept or released.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Steelhead', array['steelhead'], array['WA'], 20, null, 'total', false, '2 hatchery steelhead per day', false, null, null,
  'Release every wild steelhead (adipose or ventral fin not clipped). Open only during the river''s salmon or game fish seasons; check the river''s special rules.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Brook trout and lake trout', array['brook trout','lake trout','mackinaw'], array['WA'], null, null, 'total', false, 'No daily limit', false, null, null,
  'No minimum size. Some lakes have their own rules.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Bull trout and Dolly Varden', array['bull trout','dolly varden'], array['WA'], null, null, 'total', false, 'Catch and release only', true, null, null,
  'All fresh water is closed to fishing for them unless a water''s special rules say otherwise.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Kokanee', array['kokanee'], array['WA'], null, null, 'total', false, '10 per day', false, null, null,
  'No minimum size. When fishing with bait, every legal kokanee you catch counts toward the 10, kept or released.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Largemouth bass', array['largemouth'], array['WA'], null, 12, 'total', false, '5 per day in lakes', false, null, null,
  'Lakes, ponds and reservoirs: only largemouth under 12″ may be kept, except 1 over 17″. Rivers, streams and beaver ponds: no size or daily limit.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Smallmouth bass', array['smallmouth'], array['WA'], null, 14, 'total', true, '10 per day in lakes, only 1 over 14″', false, null, null,
  'Rivers, streams and beaver ponds: no size or daily limit.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Walleye', array['walleye'], array['WA'], 12, 22, 'total', true, '8 per day in lakes, only 1 over 22″', false, null, null,
  'Lakes, ponds and reservoirs: 12″ minimum. Rivers (including the Columbia and Snake) and streams: no size or daily limit unless a river''s special rules say otherwise.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Channel catfish', array['channel catfish'], array['WA'], null, null, 'total', false, '5 per day in lakes', false, null, null,
  'Rivers and streams: no limit. Other catfish and bullheads: no limit.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Tiger muskie', array['tiger muskie','tiger muskellunge'], array['WA'], 50, null, 'total', false, '1 per day', false, null, null,
  null, 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Mountain whitefish', array['whitefish'], array['WA'], null, null, 'total', false, '15 per day', false, null, null,
  'No minimum size.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Burbot', array['burbot'], array['WA'], null, null, 'total', false, '5 per day', false, null, null,
  'No minimum size.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Northern pike', array['northern pike'], array['WA'], null, null, 'total', false, 'No limit — it must be dead before you leave the water', false, null, null,
  'No size, daily or possession limit (an invasive fish).', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Sturgeon (white and green)', array['sturgeon'], array['WA'], null, null, 'fork', false, 'Catch and release only', true, null, null,
  'White sturgeon may be kept only in the Columbia River between Bonneville and McNary dams: 1 per day, 38–54″ fork length (43″ minimum above The Dalles Dam), 2 per year. Everywhere else, including the ocean and Puget Sound, catch and release only. Green sturgeon: never. Any sturgeon over 55″ fork length must stay in the water.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Chinook (king) salmon', array['chinook','king salmon'], array['WA'], 24, null, 'total', false, '1 Chinook per day in most marine areas', false, null, null,
  'Ocean Areas 3–4 (La Push, Neah Bay): 24″ minimum; Areas 1–2 and Puget Sound: 22″. Seasons are short and differ by marine area and river (summer ocean seasons start June 20), and many areas release wild (unclipped) Chinook. Rivers are closed to salmon unless a river''s special rules open it.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Coho (silver) salmon', array['coho','silver salmon'], array['WA'], 16, null, 'total', false, '2 salmon per day', false, null, null,
  'Many areas release wild (unclipped) coho. Seasons differ by marine area and river.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Pink, chum and sockeye salmon', array['pink salmon','humpy','chum','sockeye'], array['WA'], null, null, 'total', false, '2 salmon per day (salmon together)', false, null, null,
  'No minimum size. Some areas make you release chum or sockeye; check the marine area or river.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Pacific halibut', array['halibut'], array['WA'], null, null, 'total', false, '1 per day (6 per year)', false, null, null,
  'No minimum size. Seasons are set each spring by area; check WDFW''s halibut page before you go. Only one line with up to two hooks.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Lingcod', array['lingcod','ling cod'], array['WA'], 26, 36, 'total', false, '1 per day (Puget Sound)', false, '[["01-01","04-30"],["06-16","12-31"]]'::jsonb, null,
  'Puget Sound and the Strait (Areas 5–13): May 1 – June 15 only, 26–36″, 1 per day; Hood Canal: closed. Ocean coast (Areas 1–4): 2 per day, no size limit, from the second Saturday in March to the third Saturday in October.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Rockfish', array['rockfish'], array['WA'], null, null, 'total', false, 'Catch and release only in Puget Sound', true, null, null,
  'Puget Sound and the eastern Strait (Areas 6–13): closed to all rockfish. Ocean coast (Areas 1–4): 7 per day in season, no size limit. Area 5 (Sekiu): only the first 1–3 black or blue/deacon rockfish. Yelloweye: release everywhere.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Cabezon', array['cabezon'], array['WA'], 18, null, 'total', false, '1 per day', false, '[["01-01","04-30"],["10-16","12-31"]]'::jsonb, null,
  'Puget Sound and the Strait (Areas 5–13): May 1 – Nov 30, 18″ minimum; Hood Canal: closed. Ocean coast (Areas 1–4): no minimum, from the second Saturday in March to the third Saturday in October.',
  'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
 ('Surfperch', array['surfperch','surf perch','seaperch','pile perch','redtail'], array['WA'], null, null, 'total', false, '10 per day (Puget Sound)', false, null, null,
  'Ocean coast: 12 per day. Shiner perch: 15 more. No size limit. Hood Canal: closed.', 'https://www.eregulations.com/assets/docs/guides/26WAFW_LR2.pdf', '2026-10-22', true),
-- ---------------- Oregon (2026 Oregon Sport Fishing Regulations: zone regulations and the Marine Zone) ----------------
 ('Trout (rainbow, cutthroat, brown, brook)', array['rainbow trout','cutthroat','brown trout','brook trout','golden trout'], array['OR'], 12, 20, 'total', true, '2 per day in streams, 5 in lakes; only 1 over 20″', false, null, null,
  '12″ minimum is the Columbia River Zone; every other zone: 8″ minimum (Snake River Zone: 6 per day, no minimum). Willamette Zone streams: catch and release. Most zones: streams open May 22 – Oct 31, lakes all year. No limit on brook or brown trout in streams in most zones. Rainbows over 16–20″ in streams count as steelhead.',
  'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Bull trout', array['bull trout'], array['OR'], null, null, 'total', false, 'Catch and release only', true, null, null,
  'Closed to fishing for bull trout in most zones; a few waters allow catch and release only.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Kokanee', array['kokanee'], array['OR'], null, null, 'total', false, '10 per day', false, null, null,
  'No size limit unless a lake''s exceptions say otherwise.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Salmon and steelhead', array['chinook','king salmon','coho','silver salmon','steelhead','sockeye','pink salmon','chum'], array['OR'], null, null, 'total', false, '2 adults per day (salmon and steelhead together)', false, null, null,
  'Plus 5 jacks (young salmon) per day; 20 adults per year. Wild coho and wild steelhead must be released in most waters, and Chinook and chum only where a zone exception allows. Ocean salmon seasons and sizes are set each April (ODFW ocean salmon page and hotline).',
  'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Largemouth and smallmouth bass', array['largemouth','smallmouth','black bass'], array['OR'], null, 15, 'total', true, '5 per day in lakes, only 1 over 15″ (Southwest Zone)', false, null, null,
  'Other zones: 5 per day in lakes, no more than 3 over 15″ (Snake River Zone: 6). Streams and the Columbia River Zone: no limit.',
  'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Walleye', array['walleye'], array['OR'], null, null, 'total', false, 'No limit', false, null, null,
  'No size limit in any zone.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Striped bass and hybrid bass', array['striped bass','striper','hybrid bass'], array['OR'], null, null, 'total', false, 'No limit', false, null, null,
  'No minimum length (Marine Zone and most zones; Ana Reservoir hybrids: 1 per day, 15″).', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Panfish and catfish', array['crappie','bluegill','sunfish','yellow perch','catfish','bullhead'], array['OR'], null, null, 'total', false, 'No limit', false, null, null,
  'No minimum length in any zone.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Sturgeon (white and green)', array['sturgeon'], array['OR'], null, null, 'fork', false, 'Catch and release only', true, null, null,
  'White and green sturgeon may not be kept in any zone or the ocean (extra chances may be announced on myodfw.com). Any sturgeon over 54″ fork length must stay in the water. One single-point barbless hook only.',
  'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Lingcod', array['lingcod','ling cod'], array['OR'], 22, null, 'total', false, '2 per day', false, null, null,
  'Ocean bottomfish seasons and depth limits are set after the book is printed; check myodfw.com/sport-bottomfish-seasons before you go.',
  'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Cabezon', array['cabezon'], array['OR'], 16, null, 'total', false, 'Part of the marine bag (set each year)', false, null, null,
  'Bag limits and seasons are set after the book is printed; check myodfw.com/sport-bottomfish-seasons.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Rockfish and greenling', array['rockfish','greenling'], array['OR'], null, null, 'total', false, 'Set each year (check ODFW''s bottomfish page)', false, null, null,
  'No minimum size. Yelloweye and quillback rockfish may never be kept. Bag limits can change during the season.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Yelloweye and quillback rockfish', array['yelloweye','quillback'], array['OR'], null, null, 'total', false, 'Never keep', true, null, null,
  'Use a descending device to send them back down.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Surfperch', array['surfperch','surf perch','seaperch','pile perch','redtail'], array['OR'], null, null, 'total', false, '15 per day (all marine perch together)', false, null, null,
  'No size limit. Open all year.', 'https://www.eregulations.com/assets/docs/guides/26ORFW_LR_2025-12-01-160200_dzlv.pdf', '2026-10-22', true),
 ('Pacific halibut', array['halibut'], array['OR'], null, null, 'total', false, 'Seasons and limits are set each April', false, null, null,
