 ('Kokanee and landlocked salmon', array['kokanee','landlocked salmon'], array['CA'], null, null, 'total', false, '5 per day (10 in possession)', false, null, null,
  'No size limit. Bucks Lake, New Bullards Bar, Pardee and Trinity Lake: 10 per day.', 'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Black bass (largemouth, smallmouth, spotted)', array['largemouth','smallmouth','spotted bass','black bass'], array['CA'], 13, null, 'total', false, '5 per day', false, null, null,
  '13″ minimum and 6 per day is the Colorado River District; lakes, reservoirs and the Delta elsewhere: 12″ minimum, 5 per day; rivers, streams and private ponds: no size limit. Some counties and waters have their own rules.',
  'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Striped bass', array['striped bass','striper'], array['CA'], 18, null, 'total', false, '2 per day', false, null, null,
