 ('Sturgeon (white and green)', array['sturgeon'], array['CA'], null, null, 'fork', false, 'Catch and release only', true, null, null,
  'White sturgeon: zero may be kept (catch and release only, mainly Oct 1 – June 30 in the Delta and lower rivers; a Sturgeon Fishing Report Card is required); any over 60″ fork length must stay in the water. Green sturgeon: never.',
  'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Catfish', array['catfish'], array['CA'], null, null, 'total', false, '10 per day (Colorado River and Southern districts)', false, null, null,
  'Most of the state: no limit. Bullheads: no limit. Some lakes have 5 per day.', 'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Sunfish and crappie', array['crappie','bluegill','sunfish','redear','pumpkinseed'], array['CA'], null, null, 'total', false, '25 per day (sunfish and crappie together)', false, null, null,
  'No size limit (Hodges and El Capitan lakes: crappie 10″ minimum).', 'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Mountain whitefish', array['mountain whitefish'], array['CA'], null, null, 'total', false, '5 per day', false, null, null,
  'Only when the water is open for trout.', 'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Northern pike', array['northern pike'], array['CA'], null, null, 'total', false, 'Must be killed and reported', false, null, null,
  'Kill it at once by removing the head, keep it, and call CalTIP (1-888-DFW-CALTIP) within 24 hours.', 'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=209090&inline', '2026-10-22', true),
 ('Ocean salmon (Chinook)', array['chinook','king salmon','salmon'], array['CA'], 24, null, 'total', false, '2 per day', false, '[["01-01","04-30"],["11-01","12-31"]]'::jsonb, null,
  '2026 ocean seasons: 20″ minimum; from April 2027 south of Point Arena: 24″. The ocean is closed from Nov 1 until the 2027 openers (April 3 south of Cape Mendocino, May 1 north). Seasons differ by area and can close early; call the salmon hotline (800) 662-9825. Rivers: see the freshwater booklet.',
  'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=239985&inline', '2026-10-22', true),
 ('Coho (silver) salmon', array['coho','coho salmon','silver salmon'], array['CA'], null, null, 'total', false, 'May not be kept', true, null, null,
  'Coho salmon may never be taken or kept in California ocean waters.', 'https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=239985&inline', '2026-10-22', true),
 ('Rockfish', array['rockfish','yellowtail rockfish'], array['CA'], null, null, 'total', false, '10 per day (rockfish, cabezon and greenlings together)', false, '[["01-01","03-31"]]'::jsonb, null,
  'Only 1 copper, 2 canary and 2 vermilion (4 in the Northern area). Boats: closed Jan 1 – Mar 31 everywhere; the Southern area (Point Conception to Mexico) fishes inside 50 fathoms only July–Sept and is closed to nearshore rockfish Oct–Dec. Shore anglers and divers may fish all year. Yelloweye, quillback, cowcod and bronzespotted: never.',
  'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-10-22', true),
 ('Yelloweye, quillback, cowcod and bronzespotted rockfish', array['yelloweye','quillback','cowcod','bronzespotted'], array['CA'], null, null, 'total', false, 'Never keep', true, null, null,
  'No retention at any time, at any depth. Use a descending device to send them back down.', 'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-10-22', true),
 ('Cabezon and greenling', array['cabezon','greenling'], array['CA'], null, null, 'total', false, 'Part of the 10 rockfish, cabezon and greenlings', false, '[["01-01","03-31"]]'::jsonb, null,
  'No minimum size. Boats: closed Jan 1 – Mar 31 everywhere, and the Southern area is closed Oct–Dec. Shore anglers and divers may fish all year.',
  'https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary', '2026-10-22', true),
 ('Lingcod', array['lingcod','ling cod'], array['CA'], 22, null, 'total', false, '2 per day', false, '[["01-01","03-31"]]'::jsonb, null,
  'Boats: closed Jan 1 – Mar 31 everywhere; the Southern area fishes inside 50 fathoms only July–Sept and outside 50 fathoms only Oct–Dec. Shore anglers and divers may fish all year. Fillets at least 14″ with the skin on.',
